def gen(rng):
    def fmt(v, k):
        return str(len(v)) + '\n' + ' '.join(map(str, v)) + '\n' + str(k)
    tests = [fmt([5], 1), fmt([1, 2], 1), fmt([1, 2], 2), fmt([7, 7, 7], 2), fmt([-10**9, 10**9], 2)]
    for n in (3, 4, 6, 9, 15, 25):
        for _ in range(2):
            v = [rng.randint(-20, 20) for _ in range(n)]
            tests.append(fmt(v, rng.randint(1, n)))
    N = 10**5
    for k in (1, N, N // 2 + 1, rng.randint(1, N)):
        tests.append(fmt([rng.randint(-10**9, 10**9) for _ in range(N)], k))
    return tests

